        public static byte GetAccuracy(ushort move, EntityContext context) => context switch
        {
            Gen4 => GetAccuracy(move, MoveAccuracy_DP),
            Gen7b => GetAccuracy(move, MoveAccuracy_GG),
            Gen8 or Gen8b => GetAccuracy(move, MoveAccuracy_SWSH),
            Gen8a => GetAccuracy(move, MoveAccuracy_LA),
            _ => GetAccuracy(move, MoveAccuracy_SV),
        };

        private static byte GetAccuracy(ushort move, ReadOnlySpan<byte> accuracy)
        {
            if (move >= accuracy.Length)
                return 0;
            return accuracy[move];
        }
        public static byte GetCategory(ushort move, EntityContext context) => context switch
        {
            Gen4 => GetCategory(move, MoveCategory_DP),
            Gen7b => GetCategory(move, MoveCategory_GG),
            Gen8 or Gen8b => GetCategory(move, MoveCategory_SWSH),
            Gen8a => GetCategory(move, MoveCategory_LA),
            _ => GetCategory(move, MoveCategory_SV),
        };

        private static byte GetCategory(ushort move, ReadOnlySpan<byte> categories)
        {
            if (move >= categories.Length)
                return 0;
            return categories[move];
        }
        public static byte GetPower(ushort move, EntityContext context) => context switch
        {
            Gen4 => GetPower(move, MovePower_DP),
            Gen7b => GetPower(move, MovePower_GG),
            Gen8 or Gen8b => GetPower(move, MovePower_SWSH),
            Gen8a => GetPower(move, MovePower_LA),
            _ => GetPower(move, MovePower_SV),
        };

        private static byte GetPower(ushort move, ReadOnlySpan<byte> powers)
        {
            if (move >= powers.Length)
                return 0;
            return powers[move];
        }
